+package org.openrewrite.flix;
+
+import org.jspecify.annotations.Nullable;
+import org.openrewrite.ExecutionContext;
+import org.openrewrite.Parser;
+import org.openrewrite.SourceFile;
+import org.openrewrite.Tree;
+import org.openrewrite.flix.internal.FlixParserBridge;
+import org.openrewrite.flix.tree.Flix;
+import org.openrewrite.internal.EncodingDetectingInputStream;
+import org.openrewrite.marker.Markers;
+import org.openrewrite.tree.ParseError;
+
+import java.nio.file.Path;
+import java.util.stream.Stream;
+
+/**
+ * Parses Flix source into a lossless {@link Flix.CompilationUnit} using the
+ * vendored, decoupled Flix front-end (via {@link FlixParserBridge}). The current
+ * phase validates that the source lexes and parses and retains it verbatim; a
+ * later phase maps the {@code SyntaxTree} to rich LST nodes.
+ */
+public class FlixParser implements Parser {
+
+    @Override
+    public Stream<SourceFile> parseInputs(Iterable<Input> sources, @Nullable Path relativeTo, ExecutionContext ctx) {
+        return acceptedInputs(sources).map(input -> {
+            EncodingDetectingInputStream is = input.getSource(ctx);
+            String source = is.readFully();
+            Path path = input.getRelativePath(relativeTo);
+            try {
+                // Run the vendored front-end; diagnostics are surfaced as markers in a later phase.
+                FlixParserBridge.parse(path.toString(), source);
+                Flix.CompilationUnit cu = new Flix.CompilationUnit(
+                        Tree.randomId(),
+                        path,
+                        Markers.EMPTY,
+                        is.getCharset().name(),
+                        is.isCharsetBomMarked(),
+                        null,
+                        null,
+                        source);
+                return requirePrintEqualsInput(cu, input, relativeTo, ctx);
+            } catch (Throwable t) {
+                ctx.getOnError().accept(t);
+                return ParseError.build(this, input, relativeTo, ctx, t);
+            }
+        });
+    }
+
+    @Override
+    public boolean accept(Path path) {
+        return path.toString().endsWith(".flix");
+    }
+
+    @Override
+    public Path sourcePathFromSourceText(Path prefix, String sourceCode) {
+        return prefix.resolve("source.flix");
+    }
+
+    public static Builder builder() {
+        return new Builder();
+    }
+
+    public static class Builder extends Parser.Builder {
+
+        public Builder() {
+            super(Flix.CompilationUnit.class);
+        }
+
+        @Override
+        public FlixParser build() {
+            return new FlixParser();
+        }
+
+        @Override
+        public String getDslName() {
+            return "flix";
+        }
+    }
+}

