+package org.openrewrite.flix;
+
+import org.openrewrite.SourceFile;
+import org.openrewrite.Tree;
+import org.openrewrite.TreeVisitor;
+import org.openrewrite.flix.tree.Flix;
+
+public class FlixVisitor<P> extends TreeVisitor<Tree, P> {
+
+    @Override
+    public boolean isAcceptable(SourceFile sourceFile, P p) {
+        return sourceFile instanceof Flix;
+    }
+
+    @Override
+    public String getLanguage() {
+        return "flix";
+    }
+
+    public Tree visitCompilationUnit(Flix.CompilationUnit cu, P p) {
+        return cu.withMarkers(visitMarkers(cu.getMarkers(), p));
+    }
+}

