+package org.openrewrite.flix.internal;
+
+import org.openrewrite.PrintOutputCapture;
+import org.openrewrite.Tree;
+import org.openrewrite.flix.FlixVisitor;
+import org.openrewrite.flix.tree.Flix;
+
+/**
+ * Lossless printer. Until rich nodes exist, it re-emits the source retained on
+ * the {@link Flix.CompilationUnit} verbatim, guaranteeing parse -> print byte
+ * equality.
+ */
+public class FlixPrinter<P> extends FlixVisitor<PrintOutputCapture<P>> {
+
+    @Override
+    public Tree visitCompilationUnit(Flix.CompilationUnit cu, PrintOutputCapture<P> p) {
+        p.append(cu.getSource());
+        return cu;
+    }
+}

