+package org.openrewrite.flix.tree;
+
+import lombok.AccessLevel;
+import lombok.AllArgsConstructor;
+import lombok.EqualsAndHashCode;
+import lombok.Value;
+import lombok.With;
+import org.jspecify.annotations.Nullable;
+import org.openrewrite.Checksum;
+import org.openrewrite.Cursor;
+import org.openrewrite.FileAttributes;
+import org.openrewrite.PrintOutputCapture;
+import org.openrewrite.SourceFile;
+import org.openrewrite.Tree;
+import org.openrewrite.TreeVisitor;
+import org.openrewrite.flix.FlixVisitor;
+import org.openrewrite.flix.internal.FlixPrinter;
+import org.openrewrite.marker.Markers;
+
+import java.nio.charset.Charset;
+import java.nio.charset.StandardCharsets;
+import java.nio.file.Path;
+import java.util.UUID;
+
+/**
+ * The Flix LST. During the initial phase this holds only a lossless
+ * {@link CompilationUnit} that retains the original source verbatim; rich
+ * {@code Flix.*}/{@code J.*} nodes are introduced in later phases without ever
+ * regressing already-mapped syntax to {@link org.openrewrite.marker.Markers}-less
+ * {@code J.Unknown}.
+ */
+public interface Flix extends Tree {
+
+    @SuppressWarnings("unchecked")
+    @Override
+    default <R extends Tree, P> R accept(TreeVisitor<R, P> v, P p) {
+        return (R) acceptFlix(v.adapt(FlixVisitor.class), p);
+    }
+
+    @Nullable
+    default <P> Tree acceptFlix(FlixVisitor<P> v, P p) {
+        return v.defaultValue(this, p);
+    }
+
+    @Override
+    default <P> boolean isAcceptable(TreeVisitor<?, P> v, P p) {
+        return v.isAdaptableTo(FlixVisitor.class);
+    }
+
+    /**
+     * A parsed Flix source file. For now the tree is a thin, lossless wrapper
+     * around the source text: the vendored front-end validates that the source
+     * lexes and parses, and the printer re-emits the retained source so that
+     * parse -> print byte equality holds trivially.
+     */
+    @Value
+    @With
+    @AllArgsConstructor
+    @EqualsAndHashCode(onlyExplicitlyIncluded = true, callSuper = false)
+    class CompilationUnit implements Flix, SourceFile {
+
+        @EqualsAndHashCode.Include
+        UUID id;
+
+        Path sourcePath;
+
+        Markers markers;
+
+        @Nullable
+        @With(AccessLevel.PRIVATE)
+        String charsetName;
+
+        boolean charsetBomMarked;
+
+        @Nullable
+        FileAttributes fileAttributes;
+
+        @Nullable
+        Checksum checksum;
+
+        /** The original source, retained verbatim for lossless printing. */
+        String source;
+
+        @Override
+        public Charset getCharset() {
+            return charsetName == null ? StandardCharsets.UTF_8 : Charset.forName(charsetName);
+        }
+
+        @Override
+        public SourceFile withCharset(Charset charset) {
+            return withCharsetName(charset.name());
+        }
+
+        @Override
+        public <P> TreeVisitor<?, PrintOutputCapture<P>> printer(Cursor cursor) {
+            return new FlixPrinter<>();
+        }
+
+        public <P> Tree acceptFlix(FlixVisitor<P> v, P p) {
+            return v.visitCompilationUnit(this, p);
+        }
+    }
+}

