+package org.openrewrite.flix;
+
+import org.junit.jupiter.api.Test;
+import org.openrewrite.InMemoryExecutionContext;
+import org.openrewrite.SourceFile;
+import org.openrewrite.flix.tree.Flix;
+
+import java.util.List;
+
+import static org.assertj.core.api.Assertions.assertThat;
+
+class FlixParserTest {
+
+    private List<SourceFile> parse(String source) {
+        return FlixParser.builder().build()
+                .parse(new InMemoryExecutionContext(t -> {
+                    throw new RuntimeException(t);
+                }), source)
+                .toList();
+    }
+
+    @Test
+    void parsesAndRoundTripsExactly() {
+        String source = "" +
+                "// a leading comment\n" +
+                "def main(): Unit \\ IO =\n" +
+                "    let x = 1 + 2;\n" +
+                "    println(\"hi ${x}\")\n";
+
+        List<SourceFile> parsed = parse(source);
+
+        assertThat(parsed).hasSize(1);
+        assertThat(parsed.get(0)).isInstanceOf(Flix.CompilationUnit.class);
+        // Lossless: the printed tree is byte-for-byte the input.
+        assertThat(parsed.get(0).printAll()).isEqualTo(source);
+    }
+
+    @Test
+    void retainsSourcePath() {
+        SourceFile cu = parse("def f(): Int32 = 42\n").get(0);
+        assertThat(cu.getSourcePath().toString()).endsWith(".flix");
+    }
+}

